/* =========================================================
   SALT LEARNING FRAMEWORK
   DAVIS TECH
   MASTER CSS
   ========================================================= */


/* =========================================================
   1. CANVAS COMPATIBILITY
   ========================================================= */

.show-content.user_content.clearfix.enhanced:has(.salt-page) {
    overflow: visible !important;
    overflow-y: visible !important;
}


/* =========================================================
   2. SALT VARIABLES
   ========================================================= */

:root {
    --salt-primary: #B32839;
    --salt-primary-dark: #8F1F2D;
    --salt-primary-light: #F8EDEF;

    --salt-blue: #005A9C;
    --salt-blue-dark: #003A63;
    --salt-blue-light: #EAF3F8;

    --salt-teal: #2D6875;
    --salt-teal-light: #EAF4F5;

    --salt-text: #2F3E4D;
    --salt-text-light: #5F6B75;
    --salt-heading: #2E3D4B;

    --salt-border: #D7DADD;
    --salt-border-light: #E7E9EB;

    --salt-background: #FFFFFF;
    --salt-background-soft: #F7F8F9;

    --salt-success: #2E6B4D;
    --salt-success-light: #EAF4EE;

    --salt-warning: #C62828;
    --salt-warning-light: #FCEBEC;

    --salt-radius: 10px;
    --salt-radius-small: 7px;
}


/* =========================================================
   3. PAGE FOUNDATION
   ========================================================= */

.salt-page {
    width: 100% !important;
    max-width: 1400px !important;

    margin: 0 auto !important;
    padding: 0 24px 60px !important;

    box-sizing: border-box !important;

    color: var(--salt-text);

    font-family:
        -apple-system,
        BlinkMacSystemFont,
        "Segoe UI",
        Roboto,
        Helvetica,
        Arial,
        sans-serif;
}


.salt-page *,
.salt-page *::before,
.salt-page *::after {
    box-sizing: border-box;
}


/* =========================================================
   4. PROGRESS BAR
   ========================================================= */

#salt-progress {
    position: fixed !important;

    top: 0 !important;
    left: 0 !important;

    width: 100vw !important;
    height: 9px !important;

    margin: 0 !important;
    padding: 0 !important;

    z-index: 2147483647 !important;

    background: transparent !important;

    pointer-events: none !important;
}


#salt-progress .salt-progress-fill {
    display: block !important;

    width: 0%;

    height: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    background: #B32839 !important;

    transition: width 0.1s linear;
}


/* =========================================================
   5. MAIN LAYOUT
   ========================================================= */

.salt-layout {
    display: grid !important;

    grid-template-columns:
        210px
        minmax(0, 1fr) !important;

    gap: 32px !important;

    align-items: start !important;

    width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;

    position: relative !important;
}


/* =========================================================
   6. COURSE NAVIGATION
   ========================================================= */

.salt-sidebar {
    grid-column: 1 !important;

    position: sticky !important;

    top: 90px !important;

    align-self: start !important;

    width: 210px !important;
    min-width: 210px !important;

    max-height: calc(100vh - 110px) !important;

    overflow-y: auto !important;
    overflow-x: hidden !important;

    z-index: 100 !important;
}


.salt-sidebar-title {
    display: block !important;

    margin: 0 0 14px !important;
    padding: 0 0 10px !important;

    border-bottom: 2px solid #B32839 !important;

    color: #B32839 !important;

    font-size: 11px !important;
    font-weight: 700 !important;

    letter-spacing: 1.5px !important;

    text-transform: uppercase !important;
}


.salt-sidebar nav {
    display: flex !important;

    flex-direction: column !important;

    gap: 3px !important;

    width: 100% !important;
}


.salt-sidebar nav a {
    display: block !important;

    width: 100% !important;

    margin: 0 !important;

    padding: 9px 12px !important;

    border: 0 !important;
    border-left: 3px solid transparent !important;

    border-radius: 6px !important;

    background: transparent !important;

    color: #5F6B75 !important;

    font-size: 13px !important;
    font-weight: 500 !important;

    line-height: 1.35 !important;

    text-decoration: none !important;

    transition:
        color 0.2s ease,
        background-color 0.2s ease,
        transform 0.2s ease;
}


.salt-sidebar nav a:hover {
    color: #B32839 !important;

    background: #F8EDEF !important;

    border-left-color: #B32839 !important;

    transform: translateX(3px);
}


.salt-sidebar nav a.salt-active {
    color: #B32839 !important;

    background: #F8EDEF !important;

    border-left-color: #B32839 !important;

    font-weight: 700 !important;
}


/* =========================================================
   7. SECTIONS
   ========================================================= */

.salt-section {
    grid-column: 2 !important;

    display: block !important;

    width: 100% !important;
    min-width: 0 !important;

    margin: 0 0 44px !important;

    padding: 34px 36px !important;

    background: #FFFFFF !important;

    border: 1px solid #D7DADD !important;

    border-radius: 10px !important;

    box-shadow:
        0 2px 8px rgba(0, 0, 0, 0.06) !important;

    scroll-margin-top: 90px !important;
}


/* =========================================================
   8. TYPOGRAPHY
   ========================================================= */

.salt-section-label {
    margin-bottom: 12px !important;

    color: #B32839 !important;

    font-size: 12px !important;
    font-weight: 700 !important;

    letter-spacing: 1.6px !important;

    text-transform: uppercase !important;
}


.salt-page h1,
.salt-page h2,
.salt-page h3,
.salt-page h4 {
    color: #2E3D4B !important;

    font-family: inherit !important;

    line-height: 1.2 !important;
}


.salt-page h1 {
    margin: 0 0 18px !important;

    font-size: 44px !important;

    font-weight: 600 !important;
}


.salt-page h2 {
    margin: 0 0 16px !important;

    font-size: 32px !important;

    font-weight: 600 !important;
}


.salt-page h3 {
    margin: 0 0 10px !important;

    font-size: 22px !important;

    font-weight: 600 !important;
}


.salt-page p,
.salt-page li {
    color: #2F3E4D !important;

    font-size: 16px !important;

    line-height: 1.65 !important;
}


.salt-page p {
    margin-top: 0;
}


.salt-lead {
    max-width: 850px !important;

    margin-bottom: 26px !important;

    font-size: 18px !important;

    line-height: 1.7 !important;
}


/* =========================================================
   9. IMAGES
   ========================================================= */

.salt-image-container {
    display: block !important;

    width: 100% !important;

    margin: 28px 0 !important;
}


.salt-image {
    display: block !important;

    width: 100% !important;
    max-width: 100% !important;

    height: auto !important;

    border: 1px solid #D7DADD !important;

    border-radius: 8px !important;

    cursor: zoom-in;
}


/* Existing process image sizing */

#soldering .salt-image-container img {
    max-width: 420px !important;
    width: 100%;
    height: auto;
}


#brazing .salt-image-container img {
    max-width: 320px !important;
    width: 100%;
    height: auto;
}


#overview .salt-image-container img,
#welding .salt-image-container img {
    max-width: 100%;
    height: auto;
}

.salt-lightbox-caption {
    display: block !important;
    width: 100% !important;
    box-sizing: border-box !important;

    margin: 12px auto 0 !important;
    padding: 12px 16px !important;

    background: #f4f7f9;
    border-left: 4px solid #005A9C;
    border-radius: 6px;

    color: #333333;
    font-size: 0.95rem;
    line-height: 1.5;

    text-align: center !important;
}

/* =========================================================
   SALT DEFAULT IMAGE SIZING
   First image = larger
   Additional images = smaller
   Lightbox still displays the full-size image
   ========================================================= */

/* First instructional image in each section */
.salt-section .salt-image-container:first-of-type img.salt-image {
    width: 100% !important;
    max-width: 800px !important;
    height: auto !important;
    margin-left: auto !important;
    margin-right: auto !important;
}

/* Additional images in the same section */
.salt-section .salt-image-container:not(:first-of-type) img.salt-image {
    width: 100% !important;
    max-width: 600px !important;
    height: auto !important;
    margin-left: auto !important;
    margin-right: auto !important;
}


/* =========================================================
   MOBILE
   ========================================================= */

@media (max-width: 700px) {

    .salt-section .salt-image-container:first-of-type img.salt-image,
    .salt-section .salt-image-container:not(:first-of-type) img.salt-image {
        width: 100% !important;
        max-width: 100% !important;
    }

}

/* =========================================================
   10. OBJECTIVES
   ========================================================= */

.salt-objectives {
    display: grid !important;

    grid-template-columns:
        repeat(4, minmax(0, 1fr));

    gap: 16px;

    margin: 2rem 0;
}


.salt-objective {
    padding: 20px;

    background: #FFFFFF;

    border: 1px solid #D7DADD;

    border-radius: 10px;

    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}


.salt-objective-number {
    display: block;

    margin-bottom: 8px;

    color: #B32839;

    font-size: 12px;

    font-weight: 800;

    letter-spacing: 0.08em;
}


.salt-objective strong {
    display: block;

    margin-bottom: 6px;

    font-size: 17px;
}


.salt-objective p {
    margin: 0;

    font-size: 14px !important;

    line-height: 1.5;
}


/* =========================================================
   11. FACT CARDS
   ========================================================= */

.salt-fact-grid {
    display: grid !important;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    gap: 18px;

    margin: 2rem 0;
}


.salt-fact {
    padding: 22px;

    background: #F7F8F9;

    border: 1px solid #D7DADD;

    border-radius: 10px;
}


.salt-fact-label {
    display: block;

    margin-bottom: 8px;

    color: #B32839;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 0.08em;

    text-transform: uppercase;
}


.salt-fact strong {
    display: block;

    margin-bottom: 8px;

    font-size: 18px;
}


.salt-fact p {
    margin: 0;

    font-size: 14px !important;

    line-height: 1.55;
}


/* =========================================================
   12. CALLOUT
   ========================================================= */

.salt-callout {
    margin: 2rem 0;

    padding: 24px;

    background: #F7F8F9;

    border-left: 5px solid #B32839;

    border-radius: 8px;
}


.salt-callout-label {
    margin-bottom: 8px;

    color: #B32839;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 0.08em;

    text-transform: uppercase;
}


.salt-callout h3 {
    margin-top: 0;
}


.salt-callout p:last-child {
    margin-bottom: 0;
}

/* =========================================================
   14. COMMON MISTAKE
   ========================================================= */

.salt-mistake {
    margin: 20px 0;

    overflow: hidden;

    border: 1px solid rgba(179, 40, 57, 0.25);

    border-radius: 8px;

    background: #FFF7F7;
}


.salt-mistake .salt-reveal-button {
    background: #FFF7F7 !important;
}


.salt-mistake .salt-reveal-button:hover,
.salt-mistake.open .salt-reveal-button {
    background: #FCEBEC !important;

    color: #B32839 !important;
}


.salt-mistake .salt-reveal-content {
    background: #FFFFFF;
}


.salt-mistake-label {
    color: #B32839;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 0.08em;

    text-transform: uppercase;
}


/* =========================================================
   15. PROCESS SELECTION / KNOWLEDGE CHECK
   ========================================================= */

.salt-scenario {
    margin: 24px 0;

    padding: 24px;

    background: #FFFFFF;

    border: 1px solid #D7DADD;

    border-radius: 10px;
}


.salt-scenario-label {
    margin-bottom: 10px;

    color: #B32839;

    font-size: 11px;

    font-weight: 800;

    letter-spacing: 0.08em;

    text-transform: uppercase;
}


.salt-scenario h3 {
    margin-top: 0;
}


.salt-choice-buttons {
    display: flex !important;

    flex-wrap: wrap !important;

    gap: 10px !important;

    margin-top: 18px !important;
}


.salt-choice-buttons button,
.salt-choice {
    display: inline-flex !important;

    align-items: center !important;
    justify-content: center !important;

    min-width: 125px !important;

    padding: 11px 20px !important;

    border: 2px solid #D7DADD !important;

    border-radius: 7px !important;

    background: #FFFFFF !important;

    color: #2F3E4D !important;

    font-family: inherit !important;

    font-size: 14px !important;

    font-weight: 700 !important;

    line-height: 1.2 !important;

    cursor: pointer !important;

    transition:
        background-color 0.2s ease,
        border-color 0.2s ease,
        color 0.2s ease,
        transform 0.15s ease !important;
}


.salt-choice-buttons button:hover,
.salt-choice:hover {
    border-color: #B32839 !important;

    background: #F8EDEF !important;

    color: #B32839 !important;

    transform: translateY(-2px);
}


.salt-choice-buttons button.salt-correct,
.salt-choice.salt-correct {
    border-color: #2E7D52 !important;

    background: #EAF4EE !important;

    color: #21613E !important;
}


.salt-choice-buttons button.salt-incorrect,
.salt-choice.salt-incorrect {
    border-color: #C62828 !important;

    background: #FCEBEC !important;

    color: #A51F1F !important;

    opacity: 1 !important;
}


.salt-choice.salt-correct-answer {
    border-color: #2E7D52 !important;

    background: #EAF4EE !important;

    color: #21613E !important;
}


.salt-answer {
    display: none !important;

    margin-top: 18px;

    padding: 18px;

    background: #EAF4EE;

    border: 1px solid #BBD5C6;

    border-left: 4px solid #2E6B4D;

    border-radius: 8px;
}


.salt-answer.salt-answer-visible,
.salt-answer:not([hidden]) {
    display: block !important;
}


.salt-answer strong {
    display: block;

    margin-bottom: 6px;

    color: #21613E;
}


.salt-answer p:last-child {
    margin-bottom: 0;
}


/* =========================================================
   16. SALT FLIP CARDS — SINGLE SOURCE OF TRUTH
   Davis Tech red cards, preview copy, clear interaction cues
   ========================================================= */

.salt-flip-grid {
    display: grid !important;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 20px;
    margin: 2rem 0;
}

.salt-flip {
    position: relative !important;
    width: 100% !important;
    height: 240px !important;
    perspective: 1200px !important;
    cursor: pointer !important;
    outline: none !important;
    border-radius: 12px !important;
    -webkit-tap-highlight-color: transparent;
}

.salt-flip-inner {
    position: relative;
    width: 100%;
    height: 100%;
    transform-style: preserve-3d;
    transition: transform 0.6s cubic-bezier(0.2, 0.75, 0.25, 1) !important;
}

.salt-flip.flipped .salt-flip-inner {
    transform: rotateY(180deg) !important;
}

.salt-flip-front,
.salt-flip-back {
    position: absolute !important;
    inset: 0;
    display: flex !important;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start !important;
    box-sizing: border-box !important;
    overflow: hidden !important;
    padding: 27px 22px 52px !important;
    border: 2px solid #B32839 !important;
    border-radius: 12px !important;
    text-align: center !important;
    backface-visibility: hidden !important;
    -webkit-backface-visibility: hidden !important;
    box-shadow: 0 3px 10px rgba(0, 0, 0, 0.08);
}

/* Front: title first, then a short concept preview. */
.salt-flip .salt-flip-front {
    background: #B32839 !important;
    color: #FFFFFF !important;
    transition: box-shadow 0.25s ease, filter 0.25s ease !important;
}

.salt-flip .salt-flip-front span,
.salt-flip .salt-flip-front small,
.salt-flip .salt-flip-front h2,
.salt-flip .salt-flip-front h3,
.salt-flip .salt-flip-front h4,
.salt-flip .salt-flip-front p,
.salt-flip .salt-flip-front strong,
.salt-flip .salt-flip-front li {
    color: #FFFFFF !important;
}

.salt-flip .salt-flip-front span {
    display: block !important;
    margin: 0 0 10px !important;
    font-family: inherit !important;
    font-size: 1.5rem !important;
    font-weight: 700 !important;
    line-height: 1.2 !important;
    letter-spacing: 0.01em !important;
}

.salt-flip .salt-flip-front small {
    display: block !important;
    max-width: 32ch;
    font-size: 0.98rem !important;
    line-height: 1.45 !important;
    opacity: 0.96;
}

/* Back: the heading matches the front title, with the explanation directly below. */
.salt-flip .salt-flip-back {
    transform: rotateY(180deg);
    background: #B32839 !important;
    color: #FFFFFF !important;
}

.salt-flip .salt-flip-back h2,
.salt-flip .salt-flip-back h3,
.salt-flip .salt-flip-back h4,
.salt-flip .salt-flip-back p,
.salt-flip .salt-flip-back strong,
.salt-flip .salt-flip-back li {
    color: #FFFFFF !important;
}

.salt-flip .salt-flip-back strong {
    display: block !important;
    align-self: stretch;
    margin: 0 0 12px !important;
    font-size: 1.5rem !important;
    font-weight: 700 !important;
    letter-spacing: 0.01em !important;
    line-height: 1.2 !important;
    text-transform: none !important;
}

.salt-flip .salt-flip-back p {
    align-self: stretch;
    margin: 0 !important;
    font-size: 0.96rem !important;
    line-height: 1.48 !important;
    text-align: center !important;
}

/* Larger, persistent interaction labels on both card faces. */
.salt-flip .salt-flip-front::after {
    content: "↻  CLICK TO FLIP";
    position: absolute;
    left: 12px;
    right: 12px;
    bottom: 14px;
    display: block;
    color: rgba(255, 255, 255, 0.98) !important;
    font-family: inherit;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 1.1px;
    line-height: 1.4;
    text-align: center;
    pointer-events: none;
}

.salt-flip .salt-flip-back::after {
    content: "↻  CLICK TO RETURN";
    position: absolute;
    left: 12px;
    right: 12px;
    bottom: 14px;
    display: block;
    color: rgba(255, 255, 255, 0.98) !important;
    font-family: inherit;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 1.1px;
    line-height: 1.4;
    text-align: center;
    pointer-events: none;
}

.salt-flip:focus-visible {
    outline: 3px solid #005A9C !important;
    outline-offset: 5px !important;
}

@media (hover: hover) {
    .salt-flip:hover { z-index: 2; }
    .salt-flip:hover .salt-flip-front,
    .salt-flip:hover .salt-flip-back {
        box-shadow: 0 9px 22px rgba(0, 0, 0, 0.16);
    }
    .salt-flip:not(.flipped):hover .salt-flip-front {
        filter: brightness(1.06);
    }
}

@media (max-width: 900px) {
    .salt-flip-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 640px) {
    .salt-flip-grid { grid-template-columns: 1fr; }
    .salt-flip { height: 220px !important; }
