/* ==========================
   FILL-IN-THE-BLANK REVEAL
   ========================== */

.salt-blank {

    display:inline-flex;

    width:14rem;
    height:1.8rem;

    align-items:center;
    justify-content:center;

    border-bottom:2px solid #B32839;

    cursor:pointer;
}

/* default blank */

.salt-blank-text {
    color: transparent;
    user-select: none;
}

/* revealed answer */

.salt-blank-answer {

    opacity:0;

    color:#005A9C;

    font-weight:700;

    transition:
      opacity .35s ease;
}

/* remove underline after reveal */

.salt-blank.is-revealed {
    border-bottom-color: transparent;
}

/* keyboard accessibility */

.salt-blank:focus-visible {
    outline: 3px solid #005A9C;
    outline-offset: 4px;
}

/* reduced motion */

@media (prefers-reduced-motion: reduce) {
    .salt-blank,
    .salt-blank-answer {
        transition: none;
    }
}

.salt-blank-answer {

    color: #005A9C;
    font-weight: 700;

    opacity: 0;

    transition:
        opacity .35s ease-in-out;
}

.salt-blank.is-revealed .salt-blank-answer {

    opacity: 1;
}


/* Canvas-safe key term reveals */

.salt-table .salt-blank {
    appearance: none;
    -webkit-appearance: none;
    background: transparent;
    border: 0;
    border-bottom: 2px solid currentColor;
    border-radius: 0;
    padding: 4px 2px;
    color: inherit;
    font: inherit;
    cursor: pointer;
    text-align: left;
    min-width: 90px;
}

.salt-table .salt-blank:hover {
    border-bottom-color: #B32839;
}

.salt-table .salt-blank:focus-visible {
    outline: 2px solid #B32839;
    outline-offset: 3px;
}

.salt-table .salt-blank-answer {
    font-weight: 700;
    color: #B32839;
}

.salt-table .salt-blank [hidden] {
    display: none !important;
}


/* =========================================================
   SALT KEY TERM REVEALS — VISIBILITY FIX
   ========================================================= */

/* Initial state: display the blank, not the answer */
.salt-table .salt-blank .salt-blank-answer[hidden] {
    display: none !important;
}

/* Revealed state: show the answer */
.salt-table .salt-blank .salt-blank-answer:not([hidden]) {
    display: inline-block !important;
    visibility: visible !important;
    opacity: 1 !important;
    color: #B32839 !important;
    font-weight: 700 !important;
    transform: none !important;
}

/* Hide the blank when the answer is revealed */
.salt-table .salt-blank .salt-blank-text[hidden] {
    display: none !important;
}

/* Preserve visible blank text before revealing */
.salt-table .salt-blank .salt-blank-text:not([hidden]) {
    display: inline-block !important;
    visibility: visible !important;
    opacity: 1 !important;
}

