/* =========================================
   SALT — SUBTLE INTERACTION FEEDBACK
   ========================================= */

/* Move only the flip-card instruction. */
.salt-page .salt-flip .salt-flip-front::after,
.salt-page .salt-flip .salt-flip-back::after {
    transition: transform 180ms ease !important;
}

/* An inset border adds emphasis without changing layout. */
.salt-page .salt-reveal-button {
    transition:
        background-color 180ms ease,
        box-shadow 180ms ease !important;
}

/* Extend the underline visually without moving the text. */
.salt-page .salt-table .salt-blank {
    position: relative;
}

.salt-page .salt-table .salt-blank::after {
    content: "";
    position: absolute;
    left: 0;
    right: 0;
    bottom: -2px;
    height: 2px;
    background: #B32839;
    pointer-events: none;

    transform: scaleX(1);
    opacity: 0;

    transition:
        transform 180ms ease,
        opacity 180ms ease;
}

/* Hover effects apply to devices with a precise pointer. */
@media (hover: hover) and (pointer: fine) {
    .salt-page .salt-flip:hover .salt-flip-front::after,
    .salt-page .salt-flip:hover .salt-flip-back::after {
        transform: translateY(-3px);
    }

    .salt-page .salt-reveal-button:hover {
        box-shadow: inset 0 0 0 2px #B32839 !important;
    }

    .salt-page .salt-table .salt-blank:hover::after {
        opacity: 1;
        transform: scaleX(1.06);
    }
}

/* Give keyboard users the same feedback. */
