}

.salt-page .salt-table .salt-blank:focus-visible::after {
    opacity: 1;
    transform: scaleX(1.06);
}

/* Keep color and border cues, but remove movement
   when reduced motion is preferred. */
@media (prefers-reduced-motion: reduce) {
    .salt-page .salt-flip .salt-flip-front::after,
    .salt-page .salt-flip .salt-flip-back::after,
    .salt-page .salt-table .salt-blank::after {
        transform: none !important;
        transition: none !important;
    }

    .salt-page .salt-reveal-button {
        transition: none !important;
    }
}

